#!/usr/bin/env python3\n\"\"\"Hash identifier tool.\nDetect possible hash algorithms (MD5, SHA1, SHA224, SHA256, SHA384, SHA512)\nbased on length and character set of a given hex string.\nAccepts input via command line argument or stdin.\nOutputs JSON to stdout.\n\"\"\"\nimport sys, argparse, json, re\n\ndef identify_hash(s):\n    s = s.strip().lower()\n    if not re.fullmatch(r'[0-9a-f]+', s):\n        return []\n    length = len(s)\n    mapping = {\n        32: ['MD5'],\n        40: ['SHA1'],\n        56: ['SHA224'],\n        64: ['SHA256'],\n        96: ['SHA384'],\n        128: ['SHA512'],\n    }\n    return mapping.get(length, [])\n\ndef main():\n    parser = argparse.ArgumentParser(description='Identify possible hash algorithms.')\n    parser.add_argument('hash', nargs='?', help='Hexadecimal hash string')\n    args = parser.parse_args()\n    input_hash = args.hash\n    if input_hash is None:\n        input_hash = sys.stdin.read().strip()\n    possible = identify_hash(input_hash)\n    result = {\n        'input': input_hash,\n        'possible_algorithms': possible\n    }\n    json.dump(result, sys.stdout, ensure_ascii=False)\n    sys.stdout.write('\\n')\n\nif __name__ == '__main__':\n    main()\n